      out.write("    <script>\r\n");
      out.write("        function toggleSidebar() {\r\n");
      out.write("            document.getElementById('sidebar').classList.toggle('collapsed');\r\n");
      out.write("        }\r\n");
      out.write("        \r\n");
      out.write("        function loadContent(section) {\r\n");
      out.write("            const mainContent = document.getElementById('mainContent');\r\n");
      out.write("            \r\n");
      out.write("            // Save current section to localStorage\r\n");
      out.write("            localStorage.setItem('adminCurrentSection', section);\r\n");
      out.write("            \r\n");
      out.write("            // Update active menu item\r\n");
      out.write("            document.querySelectorAll('.sidebar-item').forEach(item => {\r\n");
      out.write("                item.classList.remove('active');\r\n");
      out.write("            });\r\n");
      out.write("            \r\n");
      out.write("            // Find and activate the correct menu item\r\n");
      out.write("            if (event && event.target) {\r\n");
      out.write("                event.target.closest('.sidebar-item').classList.add('active');\r\n");
      out.write("            } else {\r\n");
      out.write("                // For programmatic calls, find the menu item by section name\r\n");
      out.write("                const menuItems = document.querySelectorAll('.sidebar-item');\r\n");
      out.write("                menuItems.forEach(item => {\r\n");
      out.write("                    const onclick = item.getAttribute('onclick');\r\n");
      out.write("                    if (onclick && onclick.includes(\"'\" + section + \"'\")) {\r\n");
      out.write("                        item.classList.add('active');\r\n");
      out.write("                    }\r\n");
      out.write("                });\r\n");
      out.write("            }\r\n");
      out.write("            \r\n");
      out.write("            // Load content based on section\r\n");
      out.write("            fetch('/alluring-decors/admin/' + section + '?ajax=true')\r\n");
      out.write("                .then(response => response.text())\r\n");
      out.write("                .then(html => {\r\n");
      out.write("                    mainContent.innerHTML = html;\r\n");
      out.write("                })\r\n");
      out.write("                .catch(error => {\r\n");
      out.write("                    mainContent.innerHTML = `\r\n");
      out.write("                        <div class=\"dashboard-header\">\r\n");
      out.write("                            <h1 class=\"dashboard-title\">Error</h1>\r\n");
      out.write("                            <p class=\"dashboard-subtitle\">Failed to load content</p>\r\n");
      out.write("                        </div>\r\n");
      out.write("                    `;\r\n");
      out.write("                });\r\n");
      out.write("        }\r\n");
      out.write("        \r\n");
      out.write("        window.openModal = function(title, formHtml) {\r\n");
      out.write("            document.getElementById('modalTitle').textContent = title;\r\n");
      out.write("            document.getElementById('modalBody').innerHTML = formHtml;\r\n");
      out.write("            document.getElementById('formModal').style.display = 'block';\r\n");
      out.write("            document.body.style.overflow = 'hidden';\r\n");
      out.write("        }\r\n");
      out.write("        \r\n");
      out.write("        window.closeModal = function() {\r\n");
      out.write("            document.getElementById('formModal').style.display = 'none';\r\n");
      out.write("            document.body.style.overflow = 'auto';\r\n");
      out.write("        }\r\n");
      out.write("        \r\n");
      out.write("        function submitModalForm(form) {\r\n");
      out.write("            // For file uploads, use regular form submission\r\n");
      out.write("            if (form.enctype === 'multipart/form-data' || form.getAttribute('enctype') === 'multipart/form-data') {\r\n");
      out.write("                closeModal();\r\n");
      out.write("                form.submit();\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            \r\n");
      out.write("            const submitBtn = form.querySelector('button[type=\"submit\"]');\r\n");
      out.write("            const originalText = submitBtn.innerHTML;\r\n");
      out.write("            \r\n");
      out.write("            // Show loading state\r\n");
      out.write("            submitBtn.innerHTML = '<span class=\"loading\"></span>Saving...';\r\n");
      out.write("            submitBtn.classList.add('btn-loading');\r\n");
      out.write("            \r\n");
      out.write("            const formData = new FormData(form);\r\n");
      out.write("            const action = form.getAttribute('action');\r\n");
      out.write("            \r\n");
      out.write("            fetch(action, {\r\n");
      out.write("                method: 'POST',\r\n");
      out.write("                body: formData\r\n");
      out.write("            })\r\n");
      out.write("            .then(response => {\r\n");
      out.write("                if (response.ok) {\r\n");
      out.write("                    closeModal();\r\n");
      out.write("                    showSuccessMessage('Operation completed successfully!');\r\n");
      out.write("                    const currentSection = localStorage.getItem('adminCurrentSection');\r\n");
      out.write("                    if (currentSection) {\r\n");
      out.write("                        loadContent(currentSection);\r\n");
      out.write("                    }\r\n");
      out.write("                } else {\r\n");
      out.write("                    return response.text().then(text => {\r\n");
      out.write("                        throw new Error(`Server error (");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${response.status}", java.lang.String.class, (javax.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write(')');
      out.write(':');
      out.write(' ');
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${text}", java.lang.String.class, (javax.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("`);\r\n");
      out.write("                    });\r\n");
      out.write("                }\r\n");
      out.write("            })\r\n");
      out.write("            .catch(error => {\r\n");
      out.write("                alert('Error submitting form: ' + error.message);\r\n");
      out.write("            })\r\n");
      out.write("            .finally(() => {\r\n");
      out.write("                submitBtn.innerHTML = originalText;\r\n");
      out.write("                submitBtn.classList.remove('btn-loading');\r\n");
      out.write("            });\r\n");
      out.write("        }\r\n");
      out.write("        \r\n");
      out.write("        // Global functions for all admin forms\r\n");
