      out.write("                        '<div style=\"background: #f8f9fa; padding: 15px; border-radius: 8px; border-left: 4px solid #D4A017;\"><strong>Name:</strong><br>' + (feedback.name || 'Anonymous') + '</div>' +\r\n");
      out.write("                        '<div style=\"background: #f8f9fa; padding: 15px; border-radius: 8px; border-left: 4px solid #D4A017;\"><strong>Email:</strong><br>' + (feedback.email || 'Not provided') + '</div>' +\r\n");
      out.write("                        '<div style=\"background: #f8f9fa; padding: 15px; border-radius: 8px; border-left: 4px solid #D4A017;\"><strong>Type:</strong><br>' + (feedback.type || 'General') + '</div>' +\r\n");
      out.write("                        '</div>' +\r\n");
      out.write("                        '<div style=\"background: #f8f9fa; padding: 20px; border-radius: 8px; border-left: 4px solid #164e31; margin-bottom: 20px;\"><strong>Message:</strong><br>' +\r\n");
