      out.write("        function generateStars(rating) {\r\n");
      out.write("            let stars = '';\r\n");
      out.write("            for (let i = 1; i <= 5; i++) {\r\n");
      out.write("                if (i <= rating) {\r\n");
      out.write("                    stars += '<i class=\"fas fa-star\" style=\"color: #ffc107;\"></i>';\r\n");
      out.write("                } else {\r\n");
      out.write("                    stars += '<i class=\"far fa-star\" style=\"color: #dee2e6;\"></i>';\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("            return stars + ' (' + rating + '/5)';\r\n");
      out.write("        }\r\n");
