      out.write("        function showSuccessMessage(message) {\r\n");
      out.write("            // Remove existing success message\r\n");
      out.write("            const existingMsg = document.querySelector('.success-message');\r\n");
      out.write("            if (existingMsg) {\r\n");
      out.write("                existingMsg.remove();\r\n");
      out.write("            }\r\n");
      out.write("            \r\n");
      out.write("            // Create and show new success message\r\n");
      out.write("            const successDiv = document.createElement('div');\r\n");
      out.write("            successDiv.className = 'success-message';\r\n");
      out.write("            successDiv.innerHTML = '<i class=\"fas fa-check-circle\"></i> ' + message;\r\n");
      out.write("            \r\n");
      out.write("            const mainContent = document.getElementById('mainContent');\r\n");
      out.write("            mainContent.insertBefore(successDiv, mainContent.firstChild);\r\n");
      out.write("            \r\n");
      out.write("            // Show the message\r\n");
      out.write("            setTimeout(() => {\r\n");
      out.write("                successDiv.style.display = 'block';\r\n");
      out.write("            }, 100);\r\n");
      out.write("            \r\n");
      out.write("            // Hide after 3 seconds\r\n");
      out.write("            setTimeout(() => {\r\n");
      out.write("                successDiv.style.display = 'none';\r\n");
      out.write("                setTimeout(() => successDiv.remove(), 300);\r\n");
      out.write("            }, 3000);\r\n");
      out.write("        }\r\n");
